fields.InputDefinition:
{
  "goal": "You are already logged in at http://localhost:4200. Go to the Home landing page (Home icon/logo or application switcher dropdown). Scroll to the 'My Applications' section and click one of the application cards (each shows an app icon, name, description, and a few nav-item chips). Verify that clicking the CARD navigates into that application — the workspace should switch to that app's view (a new/updated tab, the app's sections in the left nav, etc.), not just highlight the card. Success is that the app opens after clicking its card. Pages can take 10-30s to load in this resource-constrained environment — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 35,
  "judgeValidationCriteria": [
    "Clicking an application card in the 'My Applications' grid navigates into that application (its content/sections load)",
    "The destination reflects the app that was clicked (title/sections match the chosen card)",
    "No error messages, blank screens, or crash pages"
  ]
}
